LIMITATIONS = json.loads('["Annual premium cashflow and instantaneous shock P&L have different horizons and are not added as a guaranteed profit.", "No default probability, recovery, accrued-on-default, roll-down, funding, jump-to-default or full curve repricing is supplied."]')
ASSUMPTIONS = json.loads('["Protection BUYER and EUR are fixed explicitly to resolve the unsigned original brief/output."]')

